(() => {
  // 1. Récupération des données
  const allStages = $('Pipedrive get Stages').item.json.data;
  const chosenDateRaw = $('Parsing variables du profiling').item.json.logistique.dates_souhaitees || "";
  const scenario = $('Mettre en variable le scoring output').item.json.scenario_logistique;

  // 2. Définition du stage de secours (Suivi)
  const suiviStage = allStages.find(s => s.name.includes("Suivi"));
  const defaultId = suiviStage ? suiviStage.id : 9;

  // 3. Logique de matching pour CAS_1
  if (scenario.includes('CAS_1') && chosenDateRaw) {

    // Nettoyage de la date : on passe en minuscule et on enlève "le", "du", etc.
    // Ex: "Le 26 mars" -> "26 mars"
    const cleanDate = chosenDateRaw.toLowerCase()
      .replace(/^(le|du|au|en)\s+/g, '')
      .trim();

    // Tentative 1 : Match direct (le nom du stage contient la date nettoyée)
    let match = allStages.find(s => s.name.toLowerCase().includes(cleanDate));

    // Tentative 2 : Extraction du jour et du mois (plus robuste)
    // Cherche un nombre (jour) et un mot (mois) dans la chaîne
    if (!match) {
      const dateParts = cleanDate.match(/(\d{1,2})\s+([a-zûé]+)/i);
      if (dateParts) {
        const day = dateParts[1];   // "26"
        const month = dateParts[2]; // "mars"

        match = allStages.find(s => {
          const stageName = s.name.toLowerCase();
          return stageName.includes(day) && stageName.includes(month);
        });
      }
    }

    if (match) return match.id;
  }

  // 4. Retour par défaut vers Suivi
  return defaultId;
})()
}}

