                .replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" style="color: #007BFF; text-decoration: underline;">$1</a>');
            html += `<div style="margin: 0 0 14px 0; padding: 0; font-family: Arial, sans-serif; font-size: 16px; line-height: 1.6; color: #1a1a1a;">${content}</div>`;
            paraBuffer = [];
        }
    };

    for (let line of lines) {
        const bulletMatch = line.match(/^\s*[\*\-]\s+(.*)/);
        if (bulletMatch) {
            flushPara();
            const content = bulletMatch[1]
                .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
                .replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2" style="color: #007BFF; text-decoration: underline;">$1</a>');
            html += `<table role="presentation" border="0" cellspacing="0" cellpadding="0" style="margin: 0 0 6px 20px; width: calc(100% - 20px);">
                <tr>
                    <td style="vertical-align: top; width: 16px; color: #1a1a1a; font-size: 13px; line-height: 24px;">&#9679;</td>
